<?php if(!defined('TELEDRIVE_INIT')){exit('Direct access not permitted');}require_once __DIR__.'/TelegramClient.php';require_once __DIR__.'/Helpers.php';class StorageEngine{private TelegramClient $telegram;private string $indexChannel;private string $storageChannel;const COMPACTION_THRESHOLD=50;const MANIFEST_FILENAME='master_manifest.json';const CACHE_FILE='index_cache.json';public function __construct(?TelegramClient $telegram=null){$this->telegram=$telegram?:new TelegramClient();$this->indexChannel=INDEX_CHANNEL_ID;$this->storageChannel=STORAGE_CHANNEL_ID;}public function isConfigured():bool{return!empty(TELEGRAM_BOT_TOKEN)&& !empty($this->indexChannel)&& !empty($this->storageChannel);}private function getCachePath():string{return TEMP_CHUNK_DIR.'/'.self::CACHE_FILE;}public function getFileSystemIndex(bool $forceRemote=false):array{if(!$this->isConfigured()){return['items'=>[],'pinned_message_id'=>0,'delta_count'=>0,'total_items'=>0];}$cacheFile=$this->getCachePath();if(!$forceRemote&&file_exists($cacheFile)){$cached=json_decode(@file_get_contents($cacheFile),true);if(is_array($cached)&& !empty($cached['items'])){return $cached;}}$items=[];$pinnedMsgId=0;$pinnedDocFileId=null;$deltaCount=0;try{$chatInfo=$this->telegram->getChat($this->indexChannel);if(isset($chatInfo['pinned_message'])){$pinnedMsg=$chatInfo['pinned_message'];$pinnedMsgId=(int)$pinnedMsg['message_id'];if(isset($pinnedMsg['document'])&&str_contains(strtolower($pinnedMsg['document']['file_name']??''),'manifest')){$pinnedDocFileId=$pinnedMsg['document']['file_id'];}}}catch(Exception $e){error_log("Failed to fetch getChat for index channel: ".$e->getMessage());}if($pinnedDocFileId){try{$manifestJson=$this->telegram->downloadFileContent($pinnedDocFileId);$manifestData=json_decode($manifestJson,true);if(is_array($manifestData)&&isset($manifestData['items'])){foreach($manifestData['items']as $item){$items[$item['id']]=$item;}$deltaCount=(int)($manifestData['delta_count']??0);}}catch(Exception $e){error_log("Failed to load master manifest content: ".$e->getMessage());}}$topMsgId=0;try{$ping=$this->telegram->sendMessage($this->indexChannel,"<code>sync</code>");$topMsgId=(int)($ping['message_id']??0);if($topMsgId>0){$this->telegram->deleteMessage($this->indexChannel,$topMsgId);}}catch(Exception $e){error_log("Top watermark detection note: ".$e->getMessage());}if($topMsgId>0){$endMsgId=$topMsgId-1;$startBound=($pinnedMsgId>0)?($pinnedMsgId+1):1;$startMsgId=max($startBound,$endMsgId-self::COMPACTION_THRESHOLD);}else{$startMsgId=1;$endMsgId=0;}if($startMsgId<=$endMsgId){$scanIds=range($startMsgId,$endMsgId);$rawMessages=$this->telegram->fetchMessagesBatch($this->indexChannel,$this->indexChannel,$scanIds);foreach($rawMessages as $scanId=>$fwdMsg){$text=$fwdMsg['text']??$fwdMsg['caption']??'';$cleanJson=strip_tags(html_entity_decode($text,ENT_QUOTES,'UTF-8'));$parsed=json_decode($cleanJson,true);if(is_array($parsed)){if(!empty($parsed['deleted'])&& !empty($parsed['id'])){unset($items[$parsed['id']]);continue;}if(isset($parsed['id'],$parsed['type'])){$parsed['index_message_id']=$scanId;$items[$parsed['id']]=$parsed;$deltaCount++;}}}}if($deltaCount>=self::COMPACTION_THRESHOLD){$newPinnedId=$this->rebuildAndPinManifest($items);if($newPinnedId>0){if($pinnedMsgId>0&&$pinnedMsgId!==$newPinnedId){$this->telegram->unpinChatMessage($this->indexChannel,$pinnedMsgId);}$pinnedMsgId=$newPinnedId;$deltaCount=0;}}if(empty($items)&& !$pinnedDocFileId&&file_exists($cacheFile)){$oldCached=json_decode(@file_get_contents($cacheFile),true);if(is_array($oldCached)&& !empty($oldCached['items'])){return $oldCached;}}$indexData=['items'=>array_values($items),'pinned_message_id'=>$pinnedMsgId,'delta_count'=>$deltaCount,'total_items'=>count($items),'last_synced_at'=>time()];@file_put_contents($cacheFile,json_encode($indexData,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return $indexData;}public function createFolder(string $name,string $parentId='root'):array{$folderId=Helpers::generateUUID();$name=Helpers::sanitizeFilename($name);$metadata=['id'=>$folderId,'type'=>'folder','name'=>$name,'parent_id'=>empty($parentId)?'root':$parentId,'created_at'=>time(),'updated_at'=>time()];return $this->saveMetadataEntry($metadata);}public function createFileEntry(array $fileData):array{$fileId=Helpers::generateUUID();$metadata=['id'=>$fileId,'type'=>'file','name'=>Helpers::sanitizeFilename($fileData['name']),'size'=>(int)$fileData['size'],'mime_type'=>$fileData['mime_type']??'application/octet-stream','parent_id'=>empty($fileData['parent_id'])?'root':$fileData['parent_id'],'chunks'=>$fileData['chunks']??[],'created_at'=>time(),'updated_at'=>time()];return $this->saveMetadataEntry($metadata);}private function saveMetadataEntry(array $metadata):array{$jsonPayload=json_encode($metadata,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$tgResponse=$this->telegram->sendMessage($this->indexChannel,"<code>".htmlspecialchars($jsonPayload)."</code>");$messageId=(int)$tgResponse['message_id'];$metadata['index_message_id']=$messageId;$index=$this->getFileSystemIndex();$items=$index['items'];$deltaCount=(int)($index['delta_count']??0)+1;$pinnedMsgId=(int)($index['pinned_message_id']??0);$found=false;foreach($items as&$it){if($it['id']===$metadata['id']){$it=$metadata;$found=true;break;}}if(!$found){$items[]=$metadata;}if($deltaCount>=self::COMPACTION_THRESHOLD){$newPinnedId=$this->rebuildAndPinManifest($items);if($newPinnedId>0){if($pinnedMsgId>0&&$pinnedMsgId!==$newPinnedId){$this->telegram->unpinChatMessage($this->indexChannel,$pinnedMsgId);}$index['pinned_message_id']=$newPinnedId;$deltaCount=0;}}$index['items']=array_values($items);$index['delta_count']=$deltaCount;$index['total_items']=count($items);@file_put_contents($this->getCachePath(),json_encode($index,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return $metadata;}public function renameItem(string $id,string $newName):array{$index=$this->getFileSystemIndex();$items=$index['items'];$target=null;$newName=Helpers::sanitizeFilename($newName);foreach($items as&$item){if($item['id']===$id){$item['name']=$newName;$item['updated_at']=time();$target=$item;break;}}if(!$target){throw new Exception("Item with ID {$id} not found.");}if(isset($target['index_message_id'])&&$target['index_message_id']>0){try{$jsonPayload=json_encode($target,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$this->telegram->editMessageText($this->indexChannel,(int)$target['index_message_id'],"<code>".htmlspecialchars($jsonPayload)."</code>");}catch(Exception $e){error_log("Failed to edit message text in place: ".$e->getMessage());}}$index['items']=array_values($items);@file_put_contents($this->getCachePath(),json_encode($index,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return $target;}public function moveItem(string $id,string $destinationParentId):array{$index=$this->getFileSystemIndex();$items=$index['items'];$target=null;$destParentId=empty($destinationParentId)?'root':$destinationParentId;if($id===$destParentId){throw new Exception("Cannot move an item inside itself.");}if($destParentId!=='root'){$destExists=false;foreach($items as $item){if($item['id']===$destParentId&&$item['type']==='folder'){$destExists=true;break;}}if(!$destExists){throw new Exception("Destination folder not found.");}}foreach($items as&$item){if($item['id']===$id){$item['parent_id']=$destParentId;$item['updated_at']=time();$target=$item;break;}}if(!$target){throw new Exception("Item with ID {$id} not found.");}if(isset($target['index_message_id'])&&$target['index_message_id']>0){try{$jsonPayload=json_encode($target,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$this->telegram->editMessageText($this->indexChannel,(int)$target['index_message_id'],"<code>".htmlspecialchars($jsonPayload)."</code>");}catch(Exception $e){error_log("Failed to edit message text for moveItem: ".$e->getMessage());}}$index['items']=array_values($items);@file_put_contents($this->getCachePath(),json_encode($index,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return $target;}public function deleteItem(string $id):array{$index=$this->getFileSystemIndex();$items=$index['items'];$toDelete=[];$this->collectCascadeIds($id,$items,$toDelete);$deletedCount=0;$remainingItems=[];foreach($items as $item){if(isset($toDelete[$item['id']])){$deletedCount++;if($item['type']==='file'&& !empty($item['chunks'])){foreach($item['chunks']as $chunk){if(isset($chunk['message_id'])){try{$this->telegram->deleteMessage($this->storageChannel,(int)$chunk['message_id']);}catch(Exception $e){error_log("Failed to delete storage message: ".$e->getMessage());}}}}if(isset($item['index_message_id'])&&$item['index_message_id']>0){$deleted=$this->telegram->deleteMessage($this->indexChannel,(int)$item['index_message_id']);if(!$deleted){try{$tombstone=json_encode(['id'=>$item['id'],'deleted'=>true]);$this->telegram->editMessageText($this->indexChannel,(int)$item['index_message_id'],"<code>".htmlspecialchars($tombstone)."</code>");}catch(Exception $e){error_log("Failed to tombstone index message: ".$e->getMessage());}}}}else{$remainingItems[]=$item;}}$index['items']=array_values($remainingItems);$index['total_items']=count($remainingItems);@file_put_contents($this->getCachePath(),json_encode($index,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return['deleted_count'=>$deletedCount,'remaining_count'=>count($remainingItems)];}private function collectCascadeIds(string $targetId,array $items,array&$collector):void{$collector[$targetId]=true;foreach($items as $item){if(($item['parent_id']??'root')===$targetId){$this->collectCascadeIds($item['id'],$items,$collector);}}}public function uploadStorageChunk(string $tempFilePath,string $chunkFilename,string $caption=''):array{$response=$this->telegram->sendDocument($this->storageChannel,$tempFilePath,$chunkFilename,$caption);$messageId=(int)$response['message_id'];$document=$response['document'];return['message_id'=>$messageId,'file_id'=>$document['file_id'],'file_unique_id'=>$document['file_unique_id']??'','file_name'=>$document['file_name']??$chunkFilename,'file_size'=>$document['file_size']??filesize($tempFilePath)];}public function rebuildAndPinManifest(array $items):int{$manifest=['version'=>1,'generated_at'=>time(),'total_items'=>count($items),'delta_count'=>0,'items'=>array_values($items)];$jsonStr=json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$tempPath=TEMP_CHUNK_DIR.'/'.self::MANIFEST_FILENAME;file_put_contents($tempPath,$jsonStr);$newMsgId=0;try{$docRes=$this->telegram->sendDocument($this->indexChannel,$tempPath,self::MANIFEST_FILENAME,'TeleDrive Master Manifest Checkpoint');$newMsgId=(int)$docRes['message_id'];$this->telegram->pinChatMessage($this->indexChannel,$newMsgId);}catch(Exception $e){error_log("Failed to rebuild and pin manifest: ".$e->getMessage());}finally{@unlink($tempPath);}return $newMsgId;}}